function breadcrumb(label){return `<div class="breadcrumb"><a href="#accueil">Accueil</a><span>/</span><span>${label}</span></div>`}
function editorialHero(label,title,copy,image='hero.jpg',light=false){return `<section class="editorial-hero ${light?'light':''}"><div>${breadcrumb(label)}<p class="eyebrow">MAISON VERMEIL · ${label.toUpperCase()}</p><h1>${title}</h1><p class="editorial-intro">${copy}</p></div><figure><img src="assets/${image}" alt="${light?'Solitaire en or et diamant':'Diamant brillant sur un écrin vert profond'}" width="720" height="640"><figcaption>VISUEL DE SYNTHÈSE · COLLECTION DE DÉMONSTRATION</figcaption></figure></section>`}
function pageCTA(title='Votre histoire mérite sa propre signature.',copy='Une idée précise ou une première envie : préparez votre projet avec la Maison.'){return `<section class="page-cta"><p class="eyebrow">UN DIALOGUE, UNE CRÉATION</p><h2>${title}</h2><p>${copy}</p><a class="button gold" href="#rendez-vous">Prendre rendez-vous</a></section>`}
function faqBlock(items){return `<div class="page-faq">${items.map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</div>`}
function decorateCatalog(type,onlyFavorites){if(onlyFavorites||type==='tous')return;const diamonds=type==='diamants';document.title=(diamonds?'Diamants':'Bagues')+' — Maison Vermeil';$('.page-intro').outerHTML=editorialHero(diamonds?'Diamants':'Bagues',diamonds?'La lumière,<br>à l’état <em>pur.</em>':'Un instant.<br>Pour <em>toujours.</em>',diamonds?'Choisissez la pierre qui vous ressemble. Une sélection de brillants naturels et de laboratoire, présentés avec leurs caractéristiques.':'Des lignes essentielles, une pierre en majesté. Découvrez quatre solitaires et imaginez le vôtre. ',diamonds?'hero.jpg':'ring-1.jpg',!diamonds);$('.catalog-layout').insertAdjacentHTML('afterbegin',`<div class="collection-heading"><div><p class="eyebrow">${diamonds?'LES PIERRES':'LES SOLITAIRES'}</p><h2>${diamonds?'Trouvez votre diamant.':'Choisissez votre signature.'}</h2></div><a class="text-link" href="${diamonds?'#guide-diamants':'#guide-tailles'}">${diamonds?'Comprendre les critères':'Choisir son tour de doigt'}</a></div><p class="notice">Prix et disponibilités illustratifs. ${diamonds?'Les deux pierres de démonstration sont de taille brillant.':'Le métal et le tour de doigt se choisissent sur chaque fiche.'}</p>`);$('#main').insertAdjacentHTML('beforeend',diamonds?`<section class="section origin-section"><div><p class="eyebrow">UNE ORIGINE, UN CHOIX ÉCLAIRÉ</p><h2>Naturel ou<br>de laboratoire ?</h2><a class="text-link" href="#guide-diamants">Explorer le guide des diamants</a></div><article><span class="chapter">01</span><h3>Le diamant naturel</h3><p>Formé dans la Terre, il est extrait puis taillé. Son origine et ses caractéristiques se documentent pierre par pierre.</p><button class="text-link" data-origin="Naturel">Voir les diamants naturels</button></article><article><span class="chapter">02</span><h3>Le diamant de laboratoire</h3><p>Cultivé dans un environnement contrôlé, il est présenté séparément dans notre sélection. Son origine reste explicitement indiquée.</p><button class="text-link" data-origin="Laboratoire">Voir les diamants de laboratoire</button></article></section>`:`<section class="section metal-section"><p class="eyebrow">LA NUANCE DU MÉTAL</p><h2>Trois expressions de votre style.</h2><div class="editorial-grid"><article><span class="metal-swatch yellow"></span><h3>L’or jaune</h3><p>Une teinte chaleureuse pour une présence intemporelle. Or 750‰ dans les configurations de démonstration.</p></article><article><span class="metal-swatch platinum"></span><h3>Le platine</h3><p>Un éclat blanc, discret et contemporain. Platine 950‰ proposé sur les fiches de solitaires.</p></article><article><span class="metal-swatch rose"></span><h3>L’or rose</h3><p>Une tonalité douce aux reflets cuivrés. Or 750‰ pour une interprétation plus personnelle.</p></article></div></section>`);$('#main').insertAdjacentHTML('beforeend',pageCTA());}
function bespokePage(){document.title='Création sur mesure — Maison Vermeil';$('#main').innerHTML=editorialHero('Sur mesure','Une idée.<br>Votre <em>signature.</em>','Une bague commence par une émotion. Explorez les formes et les matières pour dessiner les contours de votre projet.','ring-3.jpg',true)+`<section class="section process-section"><div><p class="eyebrow">LE PARCOURS DE CRÉATION</p><h2>De l’intuition<br>à la pièce.</h2><p>Un aperçu des étapes à définir avec votre joaillier. Ce parcours présente le service envisagé ; aucun atelier réel n’est encore connecté.</p></div><ol class="process-list"><li><span>01</span><div><h3>Partager une intention</h3><p>L’occasion, vos inspirations et votre budget dessinent le point de départ.</p></div></li><li><span>02</span><div><h3>Choisir une pierre</h3><p>Origine, taille, poids et nuances : chaque choix participe à l’équilibre de la bague.</p></div></li><li><span>03</span><div><h3>Préciser les lignes</h3><p>Le métal, le serti et les proportions donnent forme à votre intention.</p></div></li><li><span>04</span><div><h3>Valider le projet</h3><p>Un devis, un dessin et un délai seraient à valider avant toute fabrication réelle.</p></div></li></ol></section><section class="section project-builder"><div><p class="eyebrow">LE PREMIER CROQUIS EST UNE ENVIE</p><h2>Imaginez votre bague.</h2><p>Composez un premier brief. Il pourra accompagner votre formulaire de rendez-vous.</p><p class="notice">Cet outil prépare une intention : il ne calcule pas de devis et ne représente pas une fabrication disponible.</p></div><form id="brief-form"><div class="form-grid"><label class="field">Taille du diamant<select name="shape">${shapes.map(s=>`<option>${s}</option>`).join('')}</select></label><label class="field">Origine<select name="origin"><option>Naturel</option><option>Laboratoire</option><option>À déterminer</option></select></label><label class="field">Métal<select name="metal"><option>Or jaune 750‰</option><option>Platine 950‰</option><option>Or rose 750‰</option></select></label><label class="field">Budget envisagé<select name="budget"><option>À définir ensemble</option><option>Moins de 3 000 €</option><option>3 000 à 5 000 €</option><option>5 000 à 10 000 €</option><option>Plus de 10 000 €</option></select></label></div><div id="brief-summary" class="brief-summary" aria-live="polite"></div><button class="button dark" type="submit">Préparer mon rendez-vous</button></form></section><section class="section narrow-section"><p class="eyebrow">VOS QUESTIONS</p><h2>Avant de commencer.</h2>${faqBlock([['Puis-je partir d’une idée encore imprécise ?','Oui. Le brief vous permet de choisir quelques préférences, sans engagement. Les détails pourront être précisés lors d’un échange lorsque le service sera connecté.'],['Quel budget prévoir ?','Le prix dépendra notamment de la pierre, du métal et de la complexité du projet. Aucun devis réel ne peut être délivré par cette démonstration.'],['Combien de temps prend une création ?','Aucun délai de fabrication n’est annoncé à ce stade. Il devra être confirmé par le professionnel chargé de votre projet.']])}</section>`;const form=$('#brief-form');function update(){const d=Object.fromEntries(new FormData(form));$('#brief-summary').textContent=`Votre intention : ${d.shape.toLowerCase()} · ${d.origin.toLowerCase()} · ${d.metal} · ${d.budget}.`}form.onchange=update;update();form.onsubmit=e=>{e.preventDefault();window.creationBrief=$('#brief-summary').textContent;location.hash='rendez-vous'};}
function housePage(){document.title='Notre Maison — Maison Vermeil';$('#main').innerHTML=editorialHero('Notre Maison','La force du détail.<br>La beauté de <em>l’essentiel.</em>','Maison Vermeil explore une joaillerie de lignes pures, où la pierre et l’émotion occupent toute la place.')+`<section class="section maison-manifesto"><p class="eyebrow">NOTRE VISION</p><blockquote>« Une pièce n’a pas besoin<br>de tout dire pour devenir<br><em>inoubliable.</em> »</blockquote><p>Un vert profond. La chaleur d’un métal. La précision d’une facette. Notre univers se construit autour de ces contrastes, avec une même intention : laisser la beauté d’une pierre s’exprimer.</p></section><section class="section house-values"><div class="section-heading"><h2>Ce qui guide notre regard.</h2><span class="eyebrow">LES TROIS ESSENTIELS</span></div><div class="editorial-grid"><article><span class="chapter">01</span><h3>La justesse</h3><p>Des proportions équilibrées et des lignes lisibles. Une esthétique qui accompagne la pierre et celui ou celle qui la porte.</p></article><article><span class="chapter">02</span><h3>La singularité</h3><p>Une forme, une nuance, une intention personnelle. Chaque projet commence par ce qui vous touche.</p></article><article><span class="chapter">03</span><h3>La transparence</h3><p>Une origine clairement distinguée et des informations explicites. Les caractéristiques de démonstration ne valent pas certification.</p></article></div></section><section class="editorial-split"><img src="assets/ring-2.jpg" alt="Solitaire Épure en platine, visuel de synthèse" loading="lazy"><div><p class="eyebrow">L’ART DU SOLITAIRE</p><h2>Une ligne pure.<br>Une présence.</h2><p>Notre collection illustrative décline quatre expressions : l’ovale, le brillant, l’émeraude et la poire. Quatre façons de faire de la lumière un langage personnel.</p><a class="button dark" href="#catalogue/bagues">Explorer les bagues</a></div></section><section class="section transparency"><h3>Une maison en devenir</h3><p>Ce site présente un univers de marque et une boutique de démonstration. Aucune histoire fondatrice, adresse d’atelier, certification ou expérience artisanale réelle n’est revendiquée. Les informations de l’entreprise seront ajoutées avant une ouverture commerciale.</p></section>`+pageCTA();}
function diamondGuide(){document.title='Guide des diamants et des 4C — Maison Vermeil';$('#main').innerHTML=editorialHero('Le guide des diamants','Apprendre à voir<br>la <em>différence.</em>','Comprendre les quatre critères qui décrivent un diamant pour choisir avec un regard plus précis.')+`<section class="section guide-grid">${[['01','Carat','Le poids, pas la dimension.','Un carat équivaut à 0,20 gramme. Deux pierres de même poids peuvent paraître différentes selon leur forme et leurs proportions.','Dans la collection : 1,00 à 2,00 ct.'],['02','Couleur','Les nuances du blanc.','Pour les diamants blancs, l’échelle usuelle s’étend de D à Z. La monture et la lumière influencent aussi la perception de la teinte.','Dans la collection : E, F et G.'],['03','Pureté','Les détails à la loupe.','La pureté décrit les inclusions et les caractéristiques de surface. Une mention VS ou VVS ne permet pas, à elle seule, de juger la beauté d’une pierre.','Dans la collection : VS1, VS2 et VVS2.'],['04','Taille','Le dialogue avec la lumière.','La forme désigne le contour de la pierre. La qualité de taille concerne ses proportions, sa symétrie et son poli : elle contribue à son éclat.','Formes présentées : brillant, ovale, émeraude, poire et coussin.']].map(([n,title,subtitle,body,note])=>`<article><span class="chapter">${n}</span><h2>${title}</h2><h3>${subtitle}</h3><p>${body}</p><small>${note}</small></article>`).join('')}</section><section class="section narrow-section"><p class="eyebrow">REGARDER AU-DELÀ DES CHIFFRES</p><h2>Les bonnes questions.</h2>${faqBlock([['Un diamant de laboratoire est-il présenté comme naturel ?','Non. Les deux origines sont distinctes dans les filtres et les fiches. L’origine d’une pierre doit être connue avant de comparer les offres.'],['Où trouver le certificat ?','Aucun certificat réel n’est fourni pour les produits illustratifs de ce site. Pour une vente réelle, demandez le rapport disponible et vérifiez qu’il correspond précisément à la pierre.'],['Quel critère faut-il privilégier ?','Le choix dépend de vos préférences et de votre budget. Regardez la pierre dans son ensemble : ses caractéristiques ne remplacent pas l’examen des visuels et des documents disponibles.']])}</section><div class="guide-end"><a class="button dark" href="#catalogue/diamants">Découvrir les diamants</a></div>`;}
function sizeGuide(){document.title='Guide des tailles de bague — Maison Vermeil';$('#main').innerHTML=`${breadcrumb('Guide des tailles')}<section class="section size-guide"><p class="eyebrow">LE CONFORT D’UNE MESURE JUSTE</p><h1>Trouvez votre<br><em>tour de doigt.</em></h1><p class="lead">Une bague doit passer l’articulation tout en restant confortable. Une mesure par un joaillier reste le meilleur point de départ.</p><div class="size-layout"><div><h2>Un premier repère</h2><p>En taille française, le nombre correspond à la circonférence intérieure approximative en millimètres. Mesurez une bague qui convient déjà au doigt concerné.</p><label class="field">Diamètre intérieur en millimètres<input id="diameter" type="number" min="14" max="23" step="0.1" placeholder="Ex. : 17,2"></label><p id="size-result" class="brief-summary" role="status">Saisissez un diamètre pour obtenir une estimation.</p><p class="notice">Estimation indicative, à confirmer avec un baguier. La largeur de l’anneau et les variations de température peuvent modifier le confort.</p></div><table class="size-table"><caption>Repères de la collection</caption><thead><tr><th scope="col">Taille française</th><th scope="col">Diamètre intérieur ≈</th></tr></thead><tbody>${[48,50,52,54,56,58,60,62].map(n=>`<tr><td>${n}</td><td>${(n/Math.PI).toLocaleString('fr-FR',{maximumFractionDigits:1})} mm</td></tr>`).join('')}</tbody></table></div><a class="button dark" href="#catalogue/bagues">Revenir aux bagues</a></section>`;$('#diameter').oninput=()=>{const n=+$('#diameter').value;$('#size-result').textContent=!n?'Saisissez un diamètre pour obtenir une estimation.':n<14||n>23?'Saisissez un diamètre compris entre 14 et 23 mm.':`Circonférence estimée : ${(n*Math.PI).toLocaleString('fr-FR',{maximumFractionDigits:1})} mm. Taille française indicative : ${Math.round(n*Math.PI)}.`};}
function contactPage(){document.title='Contact — Maison Vermeil';$('#main').innerHTML=`${breadcrumb('Contact')}<section class="section contact-page"><div><p class="eyebrow">À VOTRE ÉCOUTE</p><h1>Parlons de ce<br>qui vous <em>inspire.</em></h1><p>Une question sur une pierre, une bague ou votre projet ? Préparez votre message à la Maison.</p><div class="contact-note"><h3>Un projet sur mesure ?</h3><p>Le parcours de création vous aide à préciser vos premières envies.</p><a class="text-link" href="#sur-mesure">Imaginer ma création</a></div><p class="notice">Coordonnées et horaires de la Maison à renseigner avant l’ouverture. Aucun service de messagerie n’est connecté.</p></div><form id="contact-form"><h2>Votre message</h2><p class="notice">Démonstration : ce formulaire ne transmet aucune donnée.</p><label class="field">Votre nom<input name="name" autocomplete="name" required maxlength="100"></label><label class="field">Votre e-mail<input name="email" type="email" autocomplete="email" required></label><label class="field">Le sujet<select name="subject"><option>Une question sur un diamant</option><option>Une question sur une bague</option><option>Un projet sur mesure</option><option>Autre demande</option></select></label><label class="field">Votre message<textarea name="message" rows="5" required maxlength="3000"></textarea></label><button class="button dark" type="submit">Prévisualiser mon message</button></form></section>`;$('#contact-form').onsubmit=e=>{e.preventDefault();const data=new FormData(e.currentTarget);modal('<p class="eyebrow">APERÇU · NON ENVOYÉ</p><h2>Votre message est prêt.</h2><p id="message-preview" class="message-preview"></p><p class="notice">Aucun message n’a été transmis. Vos coordonnées ne sont pas enregistrées par ce formulaire.</p><button class="button dark" data-action="close">Revenir au formulaire</button>');$('#message-preview').textContent=data.get('message')};}
function practicalPage(){document.title='Informations pratiques — Maison Vermeil';$('#main').innerHTML=`${breadcrumb('Informations pratiques')}<section class="section narrow-section info-page"><p class="eyebrow">EN TOUTE CLARTÉ</p><h1>Vos questions,<br>nos <em>repères.</em></h1><p class="lead">Tout ce qu’il faut savoir sur le fonctionnement de cette boutique de démonstration.</p>${faqBlock([['Puis-je acheter une pièce ?','Vous pouvez explorer les produits et composer un panier. Aucun paiement ni achat réel n’est possible pour le moment. Le récapitulatif ne crée aucune commande.'],['Quels moyens de paiement sont acceptés ?','Aucun prestataire de paiement n’est connecté. Les moyens de paiement seront indiqués lors de l’ouverture commerciale. Ne transmettez aucune donnée bancaire via les formulaires.'],['Comment se passe la livraison ?','Aucune expédition n’est réalisée. Les zones desservies, les transporteurs, les frais et les délais devront être définis avant toute vente réelle.'],['Quelles sont les conditions de retour ?','Aucune politique commerciale de retour n’est actuellement proposée. Les conditions applicables aux pièces de collection et aux créations personnalisées devront être précisées avant une commande réelle.'],['Les produits sont-ils certifiés ?','Les caractéristiques sont fictives et aucun rapport de laboratoire réel n’est associé aux produits de démonstration. Aucune garantie commerciale ou certification n’est revendiquée.'],['Mon panier est-il sauvegardé ?','Oui, sur cet appareil et dans ce navigateur, lorsque le stockage local est disponible. Les favoris utilisent le même principe. Ils ne sont pas synchronisés avec un compte client.'],['Le formulaire réserve-t-il un rendez-vous ?','Non. Il affiche un aperçu et ne transmet aucune demande. Aucun créneau réel n’est bloqué.']])}<div class="info-links"><a class="button dark" href="#contact">Nous contacter</a><a class="text-link" href="#confidentialite">Données & confidentialité</a></div></section>`;}
function legalPage(privacy=false){document.title=(privacy?'Confidentialité':'Informations légales')+' — Maison Vermeil';$('#main').innerHTML=`${breadcrumb(privacy?'Confidentialité':'Informations légales')}<section class="section narrow-section info-page"><p class="eyebrow">MAISON VERMEIL</p><h1>${privacy?'Vos données,<br>en <em>transparence.</em>':'Informations<br><em>légales.</em>'}</h1>${privacy?`<h2>Panier et favoris</h2><p>Ils sont conservés dans le stockage local de votre navigateur, sur cet appareil. Aucun compte client n’est nécessaire et aucune synchronisation entre appareils n’est mise en place.</p><h2>Formulaires</h2><p>Les formulaires Contact et Rendez-vous sont des démonstrations. Leur contenu n’est pas envoyé à la Maison ni conservé dans une base de données. Le brief sur mesure reste en mémoire pendant votre navigation et disparaît au rechargement.</p><h2>Mesure d’audience</h2><p>Aucun outil de suivi publicitaire ni d’analyse d’audience n’a été ajouté au code de cette boutique. L’hébergement et l’accès privé peuvent impliquer des traitements propres au fournisseur de la plateforme.</p><button class="button dark" data-action="clear">Effacer mon panier et mes favoris</button>`:`<h2>Statut du site</h2><p>Maison Vermeil est ici présenté comme une maison imaginaire dans une boutique de démonstration. Le site ne permet aucune transaction réelle.</p><h2>Informations de l’exploitant</h2><p>L’identité juridique, les coordonnées, l’immatriculation, le responsable de publication et les informations complètes d’hébergement restent à renseigner par le futur exploitant avant l’ouverture commerciale. Cette page ne constitue pas des mentions légales définitives.</p><h2>Produits et visuels</h2><p>Les noms de produits, prix, caractéristiques et disponibilités sont illustratifs. Les visuels ont été générés pour ce projet ; ils ne représentent pas des pièces réelles. Aucun avis client, certificat, provenance ni garantie réelle n’est présenté.</p><h2>Conditions de vente</h2><p>Aucune commande n’étant acceptée, aucune condition commerciale définitive n’est proposée. Les modalités de paiement, de livraison, de retour et les conditions de vente devront être préparées avant l’activation des achats.</p><a class="text-link" href="#confidentialite">Consulter les informations sur les données</a>`}</section>`;}
function enhanceProduct(){const p=products.find(p=>location.hash==='#produit/'+p.id);if(!p)return;$('.detail-copy').insertAdjacentHTML('beforeend',`<div class="product-help"><a href="${p.type==='bagues'?'#guide-tailles':'#guide-diamants'}">${p.type==='bagues'?'Consulter le guide des tailles':'Comprendre les caractéristiques'}</a><a href="#contact">Une question sur cette pièce ?</a><a href="#informations">Livraison, paiement & retours</a></div>`);$('#main').insertAdjacentHTML('beforeend',`<section class="section related"><p class="eyebrow">PROLONGER LA DÉCOUVERTE</p><h2>${p.type==='bagues'?'D’autres expressions du solitaire.':'Imaginez sa monture.'}</h2><div class="products">${products.filter(x=>x.type==='bagues'&&x.id!==p.id).slice(0,3).map(card).join('')}</div></section>`);}
